<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('GET');$id=(int)($_GET['invoice_id']??0);if($id<=0)qbook_json(['ok'=>false,'error'=>'INVOICE_REQUIRED'],422);$db=production_db();$s=$db->prepare("SELECT * FROM qbook_invoices WHERE id=? AND status='ISSUED'");$s->execute([$id]);$i=$s->fetch();if(!$i)qbook_json(['ok'=>false,'error'=>'ISSUED_INVOICE_NOT_FOUND'],404);$ls=$db->prepare("SELECT l.*,a.name revenue_account FROM qbook_invoice_lines l JOIN qbook_accounts_chart a ON a.id=l.revenue_account_id WHERE l.invoice_id=? ORDER BY line_no");$ls->execute([$id]);$lines=$ls->fetchAll();$settings=$db->query("SELECT * FROM qbook_invoice_settings WHERE id=1")->fetch();$cache=production_report_cache_directory();if(!defined('K_PATH_CACHE'))define('K_PATH_CACHE',$cache);require_once __DIR__.'/vendor/tcpdf/tcpdf.php';$ref=billing_ref('INVOICE',$i['reference_no']);$pdf=new TCPDF('P','mm','A4',true,'UTF-8',false);$pdf->SetCreator('CEH Accounts');$pdf->SetTitle($ref);$pdf->SetPrintHeader(false);$pdf->SetPrintFooter(false);$pdf->SetMargins(15,15,15);$pdf->AddPage();$company=trim((string)($settings['company_legal_name']??''));$pdf->SetFont('dejavusans','B',18);$pdf->Cell(0,10,$company!==''?$company:'COMPANY LEGAL NAME — SETTINGS REQUIRED',0,1);$pdf->SetFont('dejavusans','',9);if($company==='')$pdf->SetTextColor(160,70,0);$pdf->MultiCell(0,6,$company!==''?(string)($settings['company_address']??''):'Invoice settings are incomplete. Legal/tax/bank details have not been invented.',0,'L');$pdf->SetTextColor(0,0,0);$pdf->Ln(5);$pdf->SetFont('dejavusans','B',16);$pdf->Cell(0,9,'INVOICE '.$ref,0,1,'R');$pdf->SetFont('dejavusans','',10);$pdf->Cell(0,6,'Client: '.$i['client_name_snapshot'],0,1);$pdf->Cell(0,6,'Invoice date: '.$i['invoice_date'],0,1);$pdf->Cell(0,6,'Terms: '.($i['terms_snapshot']?:$i['payment_term']),0,1);if($i['due_date'])$pdf->Cell(0,6,'Due date: '.$i['due_date'],0,1);$pdf->Ln(4);$pdf->SetFont('dejavusans','B',9);$pdf->Cell(12,7,'#',1);$pdf->Cell(88,7,'Description',1);$pdf->Cell(28,7,'Net',1,0,'R');$pdf->Cell(24,7,'VAT',1,0,'R');$pdf->Cell(28,7,'Gross',1,1,'R');$pdf->SetFont('dejavusans','',8);foreach($lines as$l){$pdf->Cell(12,7,(string)$l['line_no'],1);$pdf->Cell(88,7,(string)$l['description'],1);$pdf->Cell(28,7,number_format((float)$l['net_amount'],2),1,0,'R');$pdf->Cell(24,7,number_format((float)$l['vat_amount'],2),1,0,'R');$pdf->Cell(28,7,number_format((float)$l['gross_amount'],2),1,1,'R');}$pdf->Ln(3);$pdf->SetFont('dejavusans','B',10);$pdf->Cell(0,6,'Net: NGN '.number_format((float)$i['net_amount'],2),0,1,'R');$pdf->Cell(0,6,'VAT ('.billing_format_percent($i['vat_rate_snapshot']??0).'): NGN '.number_format((float)$i['vat_amount'],2),0,1,'R');$pdf->Cell(0,7,'TOTAL: NGN '.number_format((float)$i['total_amount'],2),0,1,'R');$bank=trim((string)($settings['payment_bank_details']??''));$pdf->Ln(8);$pdf->SetFont('dejavusans','',8);$pdf->MultiCell(0,6,$bank!==''?$bank:'PAYMENT BANK DETAILS — SETTINGS REQUIRED',0,'L');$bytes=$pdf->Output($ref.'.pdf','S');production_discard_output();header('Content-Type: application/pdf');header('Content-Length: '.strlen($bytes));header('Content-Disposition: attachment; filename="'.$ref.'.pdf"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');echo $bytes;exit;
